import { stableSerialize } from "./validator.js";
import type { AdminResult, AdminScope } from "./types.js";

export interface AdminIdempotencyIdentity {
  key: string;
  actorId: string;
  scope: AdminScope;
  operationId: string;
}

export interface AdminIdempotencyRecord<T = unknown> {
  identity: AdminIdempotencyIdentity;
  fingerprint: string;
  result: AdminResult<T>;
  auditId?: string;
  /** Domain completion is durable before the terminal audit is attempted. */
  audit?: {
    status: "pending" | "completed" | "not-required";
    auditId?: string;
    updatedAt: string;
  };
  createdAt: string;
}

export interface AdminIdempotencyClaim {
  identity: AdminIdempotencyIdentity;
  fingerprint: string;
  token: string;
}

export type AdminIdempotencyBeginResult<T = unknown> =
  | { status: "acquired"; claim: AdminIdempotencyClaim }
  | { status: "replay"; record: AdminIdempotencyRecord<T> }
  | {
      status: "in-progress";
      /** In-process stores may provide completion notification. Distributed stores normally return retryAfterMs. */
      wait?: Promise<AdminIdempotencyRecord<T> | undefined>;
      retryAfterMs?: number;
    };

/**
 * Atomic reservation contract. Durable implementations must make `begin` a
 * compare-and-create operation on the full identity and must fence `complete`
 * and `release` with the claim token. `release` is used only before domain
 * invocation, so a failed audit/policy dependency cannot poison a safe retry.
 * Cross-process stores should use a renewable lease or a documented stale-claim
 * recovery policy. `complete` must be safely repeatable with the same claim,
 * identity, fingerprint and result: the dispatcher retries it after ambiguous
 * dependency acknowledgement failures and never re-invokes the domain.
 */
export interface AdminIdempotencyStore {
  begin<T = unknown>(input: {
    identity: AdminIdempotencyIdentity;
    fingerprint: string;
  }): Promise<AdminIdempotencyBeginResult<T>> | AdminIdempotencyBeginResult<T>;
  complete<T = unknown>(
    claim: AdminIdempotencyClaim,
    record: AdminIdempotencyRecord<T>,
  ): Promise<void> | void;
  /**
   * Optional reconciliation hook. Implementations atomically update only a
   * completed record with the same identity and fingerprint. It lets a replay
   * close a terminal-audit gap without re-running the domain mutation.
   */
  finalizeAudit?(
    identity: AdminIdempotencyIdentity,
    fingerprint: string,
    input: { auditId: string; completedAt: string },
  ): Promise<void> | void;
  release(claim: AdminIdempotencyClaim): Promise<void> | void;
}

export function adminIdempotencyStorageKey(identity: AdminIdempotencyIdentity): string {
  return stableSerialize(identity);
}

export async function adminInputFingerprint(input: unknown): Promise<string> {
  const bytes = new TextEncoder().encode(stableSerialize(input));
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return `sha256:${Array.from(new Uint8Array(digest), (byte) =>
    byte.toString(16).padStart(2, "0"),
  ).join("")}`;
}

interface MemoryPendingEntry {
  status: "in-progress";
  fingerprint: string;
  token: string;
  wait: Promise<AdminIdempotencyRecord | undefined>;
  resolve: (record: AdminIdempotencyRecord | undefined) => void;
}

interface MemoryCompletedEntry {
  status: "completed";
  fingerprint: string;
  token: string;
  record: AdminIdempotencyRecord;
}

/** Process-local atomic test/development store. It is not durable or multi-process safe. */
export class MemoryAdminIdempotencyStore implements AdminIdempotencyStore {
  private readonly entries = new Map<string, MemoryPendingEntry | MemoryCompletedEntry>();

  begin<T = unknown>(input: {
    identity: AdminIdempotencyIdentity;
    fingerprint: string;
  }): AdminIdempotencyBeginResult<T> {
    const key = adminIdempotencyStorageKey(input.identity);
    const existing = this.entries.get(key);
    if (existing && existing.fingerprint !== input.fingerprint) {
      throw new AdminError("conflict", "The idempotency key was already used with different input.");
    }
    if (existing?.status === "completed") {
      return { status: "replay", record: structuredClone(existing.record) as AdminIdempotencyRecord<T> };
    }
    if (existing?.status === "in-progress") {
      return { status: "in-progress", wait: existing.wait as Promise<AdminIdempotencyRecord<T> | undefined> };
    }

    let resolve!: (record: AdminIdempotencyRecord | undefined) => void;
    const wait = new Promise<AdminIdempotencyRecord | undefined>((complete) => { resolve = complete; });
    const token = `claim_${crypto.randomUUID()}`;
    this.entries.set(key, { status: "in-progress", fingerprint: input.fingerprint, token, wait, resolve });
    return { status: "acquired", claim: { identity: input.identity, fingerprint: input.fingerprint, token } };
  }

  complete<T = unknown>(claim: AdminIdempotencyClaim, record: AdminIdempotencyRecord<T>): void {
    const key = adminIdempotencyStorageKey(claim.identity);
    const existing = this.entries.get(key);
    if (existing?.status === "completed" && existing.token === claim.token) {
      if (existing.fingerprint !== claim.fingerprint || record.fingerprint !== claim.fingerprint) {
        throw new AdminError("conflict", "The idempotency completion fingerprint does not match its reservation.");
      }
      existing.record = structuredClone(record) as AdminIdempotencyRecord;
      return;
    }
    if (!existing || existing.status !== "in-progress" || existing.token !== claim.token) {
      throw new AdminError("conflict", "The idempotency reservation is no longer owned by this operation.");
    }
    if (existing.fingerprint !== claim.fingerprint || record.fingerprint !== claim.fingerprint) {
      throw new AdminError("conflict", "The idempotency completion fingerprint does not match its reservation.");
    }
    const snapshot = structuredClone(record) as AdminIdempotencyRecord;
    this.entries.set(key, { status: "completed", fingerprint: claim.fingerprint, token: claim.token, record: snapshot });
    existing.resolve(structuredClone(snapshot));
  }

  finalizeAudit(
    identity: AdminIdempotencyIdentity,
    fingerprint: string,
    inp…634 tokens truncated…istry, AdminRegistryOperation } from "./registry.js";
import { adminOperationMinimumScope, assertAdminScopeHierarchy, assertAdminScopeMinimum } from "./scope.js";
import { assertAdminValue, validateAdminValue } from "./validator.js";
import type {
  AdminOperationContext,
  AdminOperationError,
  AdminOperationResult,
  AdminResult,
} from "./types.js";

export interface AdminPolicyDecision {
  allowed: boolean;
  reason?: string;
  metadata?: Readonly<Record<string, unknown>>;
}

export interface AdminPolicyEvaluator {
  authorize(request: {
    entry: AdminRegistryOperation;
    input: unknown;
    context: AdminOperationContext;
  }): Promise<AdminPolicyDecision> | AdminPolicyDecision;
  /**
   * Context-only discovery decision. If omitted, authorize is invoked with an
   * undefined input so existing contextual policies still fail closed.
   */
  discover?(request: {
    entry: AdminRegistryOperation;
    context: AdminOperationContext;
  }): Promise<AdminPolicyDecision> | AdminPolicyDecision;
}

export async function evaluateAdminDiscoveryPolicy(
  policy: AdminPolicyEvaluator | undefined,
  entry: AdminRegistryOperation,
  context: AdminOperationContext,
): Promise<AdminPolicyDecision> {
  const permissions = context.actor.permissions ?? [];
  if (!permissions.includes("*") && !permissions.includes(entry.operation.permission)) {
    return { allowed: false, reason: "The active actor cannot discover this operation." };
  }
  if (!policy) return { allowed: true };
  try {
    return policy.discover
      ? await policy.discover({ entry, context })
      : await policy.authorize({ entry, input: undefined, context });
  } catch {
    return { allowed: false, reason: "The contextual policy could not authorize discovery." };
  }
}

export interface AdminConfirmationVerifier {
  verify(request: {
    entry: AdminRegistryOperation;
    input: unknown;
    context: AdminOperationContext;
    token: string;
  }): Promise<boolean> | boolean;
}

export interface CreateAdminDispatcherOptions {
  registry: AdminCapabilityRegistry;
  policy?: AdminPolicyEvaluator;
  confirmation?: AdminConfirmationVerifier;
  audit?: AdminAuditSink;
  idempotency?: AdminIdempotencyStore;
  createAuditId?: AdminAuditIdFactory;
  now?: () => Date;
}

export interface AdminDispatchRequest {
  operationId: string;
  input: unknown;
  context: AdminOperationContext;
}

function deepFreezeAdminValue<T>(value: T): T {
  if (!value || typeof value !== "object") return value;
  if (typeof AbortSignal !== "undefined" && value instanceof AbortSignal) return value;
  for (const child of Object.values(value as Record<string, unknown>)) {
    deepFreezeAdminValue(child);
  }
  return Object.freeze(value);
}

function immutableDispatchRequest(request: AdminDispatchRequest): AdminDispatchRequest {
  const { signal, ...cloneableContext } = request.context;
  const context = structuredClone(cloneableContext) as Omit<AdminOperationContext, "signal">;
  return {
    operationId: request.operationId,
    input: deepFreezeAdminValue(structuredClone(request.input)),
    context: deepFreezeAdminValue({ ...context, ...(signal ? { signal } : {}) }),
  };
}

function outwardAdminResult<T>(
  result: AdminResult<T>,
  entry: AdminRegistryOperation,
): AdminResult<T> {
  const fields = entry.operation.redaction?.outputFields ?? [];
  const allowed = entry.operation.redaction?.allowOutputFields ?? [];
  if (result.ok === false) {
    return result.error.details === undefined
      ? result
      : {
          ...result,
          error: { ...result.error, details: redactAdminValue(result.error.details, fields) },
        };
  }
  return {
    ...result,
    data: redactAdminOutputValue(result.data, fields, allowed) as T,
    ...(result.meta === undefined
      ? {}
      : { meta: redactAdminOutputValue(result.meta, fields, allowed) as Readonly<Record<string, unknown>> }),
  };
}

export class AdminDispatcher {
  private readonly registry: AdminCapabilityRegistry;
  private readonly policy?: AdminPolicyEvaluator;
  private readonly confirmation?: AdminConfirmationVerifier;
  private readonly audit?: AdminAuditSink;
  private readonly idempotency?: AdminIdempotencyStore;
  private readonly createAuditId: AdminAuditIdFactory;
  private readonly now: () => Date;

  constructor(options: CreateAdminDispatcherOptions) {
    this.registry = options.registry;
    this.policy = options.policy;
    this.confirmation = options.confirmation;
    this.audit = options.audit;
    this.idempotency = options.idempotency;
    this.createAuditId = options.createAuditId ?? createAdminAuditId;
    this.now = options.now ?? (() => new Date());
  }

  async dispatch<T = unknown>(request: AdminDispatchRequest): Promise<AdminResult<T>> {
    const startedAt = this.now();
    let entry: AdminRegistryOperation | undefined;
    let auditId: string | undefined;
    let idempotencyClaim: AdminIdempotencyClaim | undefined;
    let idempotencyIdentity: AdminIdempotencyIdentity | undefined;
    let inputValidated = false;
    let attemptedAuditAttempted = false;
    let terminalAuditAttempted = false;
    let terminalAuditWritten = false;
    let domainInvoked = false;
    let domainCompleted = false;
    let domainResponse: AdminOperationResult<T> | undefined;
    let idempotencyPersisted = false;
    let policyMetadata: Readonly<Record<string, unknown>> | undefined;
    try {
      this.assertContext(request.context);
      entry = this.registry.requireOperation(request.operationId);
      const inputSchema = entry.operation.inputSchema;
      if (!inputSchema) throw new AdminError("internal", `Operation ${entry.operation.id} has no input schema.`);
      assertAdminValue(inputSchema, request.input);
      inputValidated = true;
      // Policy, confirmation, audit and domain execution observe one immutable
      // post-validation snapshot, preventing hooks from changing IDs, payloads,
      // actor permissions or tenant scope after validation.
      request = immutableDispatchRequest(request);

      assertAdminScopeMinimum(
        request.context.scope,
        adminOperationMinimumScope(entry.manifest, entry.operation),
      );
      const permissionDecision = this.defaultPolicy(entry, request.context);
      if (!permissionDecision.allowed) {
        throw new AdminError("forbidden", "The active actor cannot perform this operation.");
      }
      const decision = this.policy
        ? await this.policy.authorize({ entry, input: request.input, context: request.context })
        : permissionDecision;
      policyMetadata = decision.metadata;
      if (!decision.allowed) throw new AdminError("forbidden", decision.reason || "The active actor cannot perform this operation.");

      if (entry.operation.safety.requiresConfirmation) {
        const token = request.context.confirmationToken;
        if (!token) throw new AdminError("precondition_failed", "This operation requires explicit confirmation.");
        if (!this.confirmation) {
          throw new AdminError("dependency_unavailable", "Administration confirmation verification is unavailable.");
        }
        if (!(await this.confirmation.verify({ entry, input: request.input, context: request.context, token }))) {
          throw new AdminError("precondition_failed", "The operation confirmation is invalid or expired.");
        }
      }

      if (entry.operation.safety.audit === "required" && !this.audit) {
        throw new AdminError("dependency_unavailable", "A required administration audit sink is unavailable.");
      }

      const identity = this.idempotencyIdentity(entry, request.context);
      if (entry.operation.safety.classification !== "read" && entry.operation.safety.idempotent && !identity) {
        throw new AdminError("precondition_failed", "This operation requires an idempotency key.");
      }
      if (identity && !this.idempotency) {
        throw new AdminError("dependency_unavailable", "Durable administration idempotency storage is unavailable.");
      }
      if (identity && this.idempotency) {
        const reservation = await beginAdminIdempotency<T>(this.idempotency, identity, request.input);
        if (reservation.status === "replay") {
          const prior = outwardAdminResult(reservation.record.result, entry);
          const originalAuditId = reservation.record.auditId ?? prior.auditId;
