import { ciFnAdminCapability } from "./capability.js";
import type {
  CiFnDownloadArtifactInput,
  CiFnDownloadArtifactOutput,
  CiFnGetJobInput,
  CiFnGetJobOutput,
  CiFnGetRunInput,
  CiFnGetRunOutput,
  CiFnListArtifactsInput,
